    @gl.public.write
    def open_event(self, descriptor_json: str) -> str:
        value = parse(descriptor_json)
        keys = {'event_id', 'schema_id', 'schema_revision', 'title', 'issuer', 'place', 'interval_start', 'interval_end', 'occurrence_type', 'official_reference', 'source'}
